public class WhyGcDemo {

    // 把字节数换算成更好读的 MB(1 MB = 1024 * 1024 字节)
    static double toMB(long bytes) {
        return bytes / 1024.0 / 1024.0;
    }

    // 打印当前"已用内存" = 总内存(totalMemory) - 空闲内存(freeMemory)
    static long printUsed(String when) {
        Runtime rt = Runtime.getRuntime();
        long used = rt.totalMemory() - rt.freeMemory();
        System.out.printf("[%s] 已用内存(used) = %.2f MB%n", when, toMB(used));
        return used;
    }

    public static void main(String[] args) {
        System.out.println("==== Java GC 演示:对象没人用了,GC 会自动把内存收回来 ====");

        // 1) 先看分配之前的内存基线
        long before = printUsed("分配前");

        // 2) 故意分配一大块对象:200 个数组,每个 1MB,合计约 200MB 的字节
        //    这些对象都被 list 这个引用"抓着",所以暂时不能被回收
        java.util.List<byte[]> list = new java.util.ArrayList<>();
        for (int i = 0; i < 200; i++) {
            list.add(new byte[1024 * 1024]); // 1MB 的字节数组
        }
        long afterAlloc = printUsed("分配后(对象都还被引用着)");

        // 3) 关键一步:把唯一抓着这些对象的引用置为 null
        //    这样这 200MB 对象就变成"没人用的垃圾",GC 有资格回收它们
        list = null;

        // 4) 建议 JVM 现在做一次垃圾回收(只是建议,但通常会触发)
        //    注意:System.gc() 触发的是一次同步的 Full GC,
        //    这行代码返回时,回收通常已经完成,不需要再额外等待
        System.out.println(">>> 引用已置 null,调用 System.gc() 建议回收...");
        System.gc();

        // 5) 再看一次内存:应该明显下降,证明那块内存真的被收回去了
        long afterGc = printUsed("GC 之后");

        System.out.println("----------------------------------------------------");
        System.out.printf("分配阶段大约新增占用: %.2f MB%n", toMB(afterAlloc - before));
        System.out.printf("GC 之后相比分配峰值释放: %.2f MB%n", toMB(afterAlloc - afterGc));
        System.out.println("结论:在 C 语言里你得手动 free 这 200MB;在 Java 里你只是把引用丢掉,GC 帮你自动回收。");
    }
}

import java.lang.ref.Cleaner;

/**
 * 演示:Java 判断"垃圾"用的是【可达性分析】,而不是【引用计数】。
 *
 * 我们造两个对象 A 和 B,让它们【互相引用】(循环引用):
 *     A.partner = B;
 *     B.partner = A;
 * 这时如果用"引用计数"(数有几个引用指着我,为 0 才回收):
 *     A 被 B 指着,计数 = 1;B 被 A 指着,计数 = 1。
 *     就算外部没人用它们了,计数也永远 >= 1,会被【漏掉】,永远清不掉(内存泄漏)。
 *
 * 而 Java 用"可达性分析":从 GC Roots(这里是 main 方法里的局部变量 a、b)出发,
 * 能不能"走到"某个对象。把 a、b 都置为 null 后,从 GC Roots 再也走不到 A 和 B
 * (它们俩只是彼此能找到对方,但整团已经从根上断开了),所以判定为垃圾,会被回收。
 *
 * 用 Cleaner 注册回调:对象真的被回收时,会打印 "xxx 被回收了"。
 * 如果 A 和 B 都被打印 => 它们确实被回收了 => 证明 Java 用的是可达性分析,
 * 不会被循环引用骗到。
 */
public class ReachabilityDemo {

    // 一个共享的 Cleaner(可以理解为"回收事件的通知中心")
    static final Cleaner CLEANER = Cleaner.create();

    static class Node {
        final String name;
        Node partner; // 指向"搭档"对象,用来制造循环引用

        Node(String name) {
            this.name = name;
            // 注册:当【这个 Node 对象】变得不可达、被 GC 回收时,
            // 执行这个 Runnable 打印一句话。
            // 注意:回调里只能引用 name 这个 String,不能引用 Node 本身(this),
            // 否则又会让对象一直可达,反而回收不了。
            final String n = name;
            CLEANER.register(this, () -> System.out.println("[Cleaner] 对象 " + n + " 被回收了!"));
        }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("== 1. 创建 A、B 两个对象,并让它们互相引用(循环引用) ==");
        Node a = new Node("A");
        Node b = new Node("B");
        a.partner = b; // A 指向 B
        b.partner = a; // B 指向 A
        System.out.println("    A.partner = " + a.partner.name + " , B.partner = " + b.partner.name);
        System.out.println("    此刻:A 被 B 指着、B 被 A 指着 —— 引用计数法里两者计数都是 1,谁也清不掉。");

        System.out.println();
        System.out.println("== 2. 把外部引用 a、b 都置为 null(外部再也没人用它们) ==");
        a = null;
        b = null;
        System.out.println("    现在从 GC Roots(main 的局部变量)出发,已经走不到 A 和 B 了。");
        System.out.println("    它们只是彼此还连着,但整团已从'根'断开 —— 按可达性分析,它们是垃圾。");

        System.out.println();
        System.out.println("== 3. 触发 GC,看 A、B 会不会被回收 ==");
        // 多触发几次 GC,并给 Cleaner 的后台线程一点时间去执行回调
        for (int i = 0; i < 5; i++) {
            System.gc();
            Thread.sleep(200);
        }

        System.out.println();
        System.out.println("== 4. 结论 ==");
        System.out.println("    如果上面打印了 'A 被回收了' 和 'B 被回收了',");
        System.out.println("    说明循环引用的 A、B 都被回收了 => Java 用的是【可达性分析】,");
        System.out.println("    而不是会被循环引用骗到的【引用计数】。");

        // 再睡一会,确保回调线程把消息打印完
        Thread.sleep(500);
    }
}

import java.lang.ref.Cleaner;
import java.util.concurrent.TimeUnit;

/**
 * 演示 GC Roots:从"根"出发能找到的对象才算活的。
 *
 * 我们用两种 GC Root 各持有一个对象:
 *   1) 静态变量(staticHolder)—— 它本身就是一个 GC Root。
 *   2) main 方法栈里的局部变量(localHolder)—— 栈里的局部变量也是 GC Root。
 *
 * 然后把这两个引用都置 null,让对象从所有 GC Roots 都"够不着"(不可达),
 * 触发 GC 后,用 Cleaner 打印"我被回收了"来证明它真的成了垃圾被清掉。
 */
public class GcRootsDemo {

    // —— 这是一个静态变量。静态变量天然是 GC Root。
    //    只要它指向某个对象,那个对象就一定可达(活着)。
    static Data staticHolder;

    // 一个普通的数据对象。每个对象在创建时注册一个 Cleaner,
    // 当对象变得不可达并被 GC 回收时,Cleaner 会执行那段"善后"代码。
    static class Data {
        final String name;
        Data(String name) {
            this.name = name;
        }
    }

    // Cleaner 用来观察"对象是否被回收"。注意:回收动作不能引用 Data 本身,
    // 否则就又把它拉成可达了,所以这里只传一个名字字符串。
    static final Cleaner CLEANER = Cleaner.create();

    static Data createTracked(String name) {
        Data d = new Data(name);
        CLEANER.register(d, () ->
            System.out.println("    [Cleaner] 对象 '" + name + "' 已从 GC Roots 不可达,被回收了!"));
        return d;
    }

    public static void main(String[] args) throws Exception {
        System.out.println("=== GC Roots 演示开始 ===");

        // 情况一:被【局部变量】(GC Root)持有 —— 可达,活着
        Data localHolder = createTracked("局部变量持有的对象");
        // 情况二:被【静态变量】(GC Root)持有 —— 可达,活着
        staticHolder = createTracked("静态变量持有的对象");

        System.out.println("\n[阶段1] 两个对象分别被 局部变量 和 静态变量 持有。");
        System.out.println("        它们都能从 GC Roots 到达 => 都是活的。");
        System.gc();
        TimeUnit.MILLISECONDS.sleep(300);
        System.out.println("        触发了一次 GC,但没有任何 [Cleaner] 输出 => 证明它们没被回收(还活着)。");
        // 这行"使用"一下 localHolder,防止它在最后一次使用前就被活跃性分析判定为可提前回收。
        System.out.println("        (确认局部对象仍可用,name = " + localHolder.name + ")");

        System.out.println("\n[阶段2] 现在把两个引用都置为 null,切断它们与 GC Roots 的联系……");
        localHolder = null;     // 局部变量这个 GC Root 不再指向对象
        staticHolder = null;    // 静态变量这个 GC Root 不再指向对象

        // 此刻,没有任何 GC Root 能到达这两个对象 => 它们变成"不可达" => 是垃圾
        for (int i = 0; i < 5; i++) {
            System.gc();                       // 建议 JVM 做一次回收
            TimeUnit.MILLISECONDS.sleep(200);  // 给 Cleaner 后台线程一点时间打印
        }

        System.out.println("\n[阶段3] 上面应当出现两条 [Cleaner] 回收日志 => 证明:");
        System.out.println("        引用置 null 后,对象从所有 GC Roots 不可达,就被当垃圾回收了。");
        System.out.println("=== GC Roots 演示结束 ===");
    }
}

/**
 * 玩具版 GC 模拟器:用一个数组当“堆”,演示三种回收算法。
 * 数组里每个格子代表堆里的一块内存:
 *   - "__"  表示空闲格子(没放对象)
 *   - "A存" 表示对象 A,且它存活(还有人用)
 *   - "B死" 表示对象 B,且它是垃圾(没人用了)
 * 回收做的事:把“死”的对象清掉,腾出空间。
 *
 * 说明:真实 GC 里“谁存活”是靠从 GC Roots 出发的可达性分析算出来的;
 * 这里为了聚焦三种算法,直接把可达性分析的结果写成每个对象的 alive 标记。
 */
public class GcAlgorithmsDemo {

    // 一个对象:名字 + 是否存活
    static class Obj {
        String name;
        boolean alive;
        Obj(String name, boolean alive) { this.name = name; this.alive = alive; }
        public String toString() { return name + (alive ? "存" : "死"); }
    }

    static final String EMPTY = "__";

    // 把堆数组画成一行,方便肉眼看布局
    static String layout(Object[] heap) {
        StringBuilder sb = new StringBuilder("[ ");
        for (Object cell : heap) {
            sb.append(cell == null ? EMPTY : cell.toString());
            sb.append(" ");
        }
        sb.append("]");
        return sb.toString();
    }

    // 统计:空闲几个、最大连续空闲是多少(衡量碎片)
    static String stats(Object[] heap) {
        int free = 0, maxRun = 0, run = 0;
        for (Object cell : heap) {
            if (cell == null) { free++; run++; maxRun = Math.max(maxRun, run); }
            else { run = 0; }
        }
        return "空闲格=" + free + ", 最大连续空闲=" + maxRun;
    }

    public static void main(String[] args) {
        System.out.println("==========================================================");
        System.out.println(" 玩具 GC 模拟:同一份初始堆,跑三种回收算法看区别");
        System.out.println("==========================================================");

        System.out.println("\n初始堆布局(存=存活, 死=垃圾):");
        System.out.println("  " + layout(makeHeap(8)));
        System.out.println("  " + stats(makeHeap(8)));

        markSweep();
        copying();
        markCompact();

        System.out.println("\n==========================================================");
        System.out.println(" 结论速记:");
        System.out.println("  标记-清除: 简单,但回收后留下“空洞”,内存碎片化(看最大连续空闲)");
        System.out.println("  复制    : 没碎片、速度快,但要两块空间,可用内存只有一半");
        System.out.println("  标记-整理: 没碎片、不浪费空间,但要移动对象+改引用,较慢");
        System.out.println("  用在哪  : 新生代对象死得多→复制(只搬少量存活);老年代对象多且活得久→标记-整理");
        System.out.println("==========================================================");
    }

    // 造一份初始堆:A存 B死 C存 D死 E存 F死,后面补空格
    static Object[] makeHeap(int size) {
        Object[] heap = new Object[size];
        heap[0] = new Obj("A", true);
        heap[1] = new Obj("B", false);
        heap[2] = new Obj("C", true);
        heap[3] = new Obj("D", false);
        heap[4] = new Obj("E", true);
        heap[5] = new Obj("F", false);
        // heap[6], heap[7] 保持 null(空闲)
        return heap;
    }

    // ---------- 算法一:标记-清除 (Mark-Sweep) ----------
    // 思路:先“标记”谁存活,再“清除”所有死对象(就地把格子置空)。
    // 不移动存活对象,所以存活对象之间会留下空洞 -> 碎片。
    static void markSweep() {
        System.out.println("\n---------- 1) 标记-清除 Mark-Sweep ----------");
        Object[] heap = makeHeap(8);
        System.out.println("回收前: " + layout(heap) + "   " + stats(heap));

        // 清除阶段:遍历,把死的就地清空(存活对象原地不动)
        for (int i = 0; i < heap.length; i++) {
            Obj o = (Obj) heap[i];
            if (o != null && !o.alive) {
                heap[i] = null; // 清除:腾空这个格子
            }
        }
        System.out.println("回收后: " + layout(heap) + "   " + stats(heap));
        System.out.println("观察: 存活对象 A C E 原地不动,中间留下空洞 -> 内存碎片(最大连续空闲很小)");
    }

    // ---------- 算法二:复制 (Copying) ----------
    // 思路:把内存分成两半(From / To)。回收时把存活对象“搬”到 To 半区并排紧,
    // 然后整个 From 半区一次性丢弃。没碎片,但任意时刻只能用一半空间。
    static void copying() {
        System.out.println("\n---------- 2) 复制 Copying ----------");
        Object[] from = makeHeap(8);
        Object[] to   = new Object[8]; // 另一半,初始全空
        System.out.println("From 半区(回收前): " + layout(from) + "   " + stats(from));
        System.out.println("To   半区(回收前): " + layout(to)   + "   " + stats(to));

        // 把 From 里存活的对象,从头开始紧挨着搬进 To
        int next = 0;
        for (Object cell : from) {
            Obj o = (Obj) cell;
            if (o != null && o.alive) {
                to[next++] = o; // 搬过去并排紧
            }
        }
        System.out.println("搬运后 To 半区(回收后): " + layout(to) + "   " + stats(to));
        System.out.println("观察: 存活的 A C E 被搬到 To 并紧挨在一起,From 整块作废;无碎片,但耗了第二块空间");
    }

    // ---------- 算法三:标记-整理 (Mark-Compact) ----------
    // 思路:标记存活后,在同一块内存里把存活对象都往一端“挪紧”(滑动),
    // 另一端剩下的就是连续的大块空闲。无碎片,也不需要第二块空间。
    static void markCompact() {
        System.out.println("\n---------- 3) 标记-整理 Mark-Compact ----------");
        Object[] heap = makeHeap(8);
        System.out.println("回收前: " + layout(heap) + "   " + stats(heap));

        // 整理:用一个“写指针”从 0 开始,遇到存活对象就写到写指针处,然后写指针++
        int write = 0;
        for (int read = 0; read < heap.length; read++) {
            Obj o = (Obj) heap[read];
            if (o != null && o.alive) {
                heap[write++] = o;       // 把存活对象往左端挪
            }
        }
        // 写指针之后的格子全部清空
        for (int i = write; i < heap.length; i++) {
            heap[i] = null;
        }
        System.out.println("回收后: " + layout(heap) + "   " + stats(heap));
        System.out.println("观察: 存活的 A C E 全挪到左端紧挨,右端是一整块连续空闲;无碎片且只用一块空间");
    }
}

/**
 * 演示「分代收集」:新生代(Eden+Survivor) / 老年代 / 晋升。
 *
 * 思路:
 *  - 在循环里疯狂 new 一堆"用完就扔"的短命对象(临时大数组),
 *    它们生在 Eden,很快没人引用 -> 变垃圾。
 *  - Eden 很快被填满,JVM 触发 Young GC(年轻代回收)。
 *  - 同时我们保留一个"长寿"对象列表(survivors),让它们一直被引用,
 *    熬过一次次 Young GC,演示"熬过GC的对象会被复制进 Survivor、长期存活"。
 *
 * 注意:本程序运行极短(约 0.06s)、只做了几次 Young GC,
 *       长寿对象大概率尚未真正"晋升"到老年代(日志里不会出现 Old/Full GC),
 *       它演示的是 Survivor 幸存 + 复制式 Young GC 飞快清垃圾这两点。
 *
 * 配合 VM 参数 -Xlog:gc 运行,就能在 GC 日志里看到 "Pause Young" 这类行。
 */
public class GenerationalGC {

    // 这个 list 一直被 main 持有引用 => 里面的对象是"长寿对象",会熬过多次 Young GC
    private static final java.util.List<byte[]> survivors = new java.util.ArrayList<>();

    public static void main(String[] args) {
        System.out.println("=== 分代收集演示开始 ===");
        System.out.println("策略:循环里 new 大量短命对象塞满 Eden,逼 JVM 做 Young GC");
        System.out.println();

        final int rounds = 20000;        // 循环很多轮,持续制造垃圾
        final int garbageSize = 64 * 1024; // 每个垃圾对象 64KB

        long createdBytes = 0;

        for (int i = 0; i < rounds; i++) {
            // (1) 短命垃圾:new 出来后没人长期引用,下一轮就成垃圾,死在新生代
            byte[] garbage = new byte[garbageSize];
            garbage[0] = (byte) i; // 用一下,防止被编译器优化掉
            createdBytes += garbageSize;

            // (2) 偶尔留下一个长寿对象,让它反复熬过 Young GC -> 体现"幸存/为晋升做准备"
            if (i % 2000 == 0) {
                survivors.add(new byte[16 * 1024]); // 16KB 的长寿对象
            }
        }

        // 输出统计,证明我们确实分配了远超新生代容量的内存,逼出了多次 Young GC
        System.out.println("总共分配的短命对象内存:约 " + (createdBytes / 1024 / 1024) + " MB");
        System.out.println("保留的长寿对象个数(熬过GC、长期存活、最终有资格晋升老年代):" + survivors.size());

        // 打印堆内存使用情况,顺带证明大量内存被回收了(分配了上千MB,但堆远没用这么多)
        Runtime rt = Runtime.getRuntime();
        long usedMB = (rt.totalMemory() - rt.freeMemory()) / 1024 / 1024;
        long maxMB = rt.maxMemory() / 1024 / 1024;
        System.out.println("当前堆已用:约 " + usedMB + " MB / 堆上限:约 " + maxMB + " MB");
        System.out.println("(分配了上千MB却没爆堆,说明短命对象被 Young GC 回收掉了)");

        System.out.println();
        System.out.println("=== 演示结束:请看上面/下面 [gc] 开头的 JVM 日志里的 \"Pause Young\" 行 ===");
    }
}

import java.lang.management.GarbageCollectorMXBean;
import java.lang.management.ManagementFactory;
import java.util.ArrayList;
import java.util.List;

/**
 * 演示:当前 JVM 实际用的是哪个垃圾收集器,以及一次 GC 会带来怎样的 STW 暂停。
 */
public class GcDemo {
    public static void main(String[] args) throws Exception {
        // ---------- 第 1 部分:打印当前 JVM 实际使用的垃圾收集器 ----------
        System.out.println("==== 当前 JVM 实际使用的垃圾收集器 ====");
        List<GarbageCollectorMXBean> beans = ManagementFactory.getGarbageCollectorMXBeans();
        for (GarbageCollectorMXBean bean : beans) {
            System.out.println("收集器名字: " + bean.getName());
        }
        // 根据收集器名字粗略判断是哪种 GC
        String allNames = String.join(",", beans.stream().map(GarbageCollectorMXBean::getName).toList());
        String which;
        if (allNames.contains("G1")) {
            which = "G1 (JDK 9~21 的默认收集器)";
        } else if (allNames.contains("ZGC") || allNames.contains("Z")) {
            which = "ZGC (超低停顿)";
        } else if (allNames.contains("PS") || allNames.contains("Parallel")) {
            which = "Parallel (吞吐优先)";
        } else if (allNames.contains("Copy") || allNames.contains("MarkSweepCompact")) {
            which = "Serial (单线程)";
        } else {
            which = "未知 / 其他";
        }
        System.out.println("=> 推断使用的是: " + which);

        // ---------- 第 2 部分:制造垃圾,触发 GC,统计 STW 暂停 ----------
        System.out.println();
        System.out.println("==== 制造垃圾并触发 GC,观察暂停(STW)====");

        // 记录开始时的 GC 累计次数和累计暂停时间
        long gcCountBefore = 0, gcTimeBefore = 0;
        for (GarbageCollectorMXBean bean : beans) {
            gcCountBefore += bean.getCollectionCount();
            gcTimeBefore += bean.getCollectionTime();
        }

        // 疯狂分配并丢弃对象,逼着 JVM 不断回收垃圾
        long start = System.currentTimeMillis();
        for (int round = 0; round < 80; round++) {
            List<byte[]> trash = new ArrayList<>();
            for (int i = 0; i < 2000; i++) {
                trash.add(new byte[10 * 1024]); // 每块 10KB
            }
            trash.clear();          // 全部变成垃圾
            trash = null;           // 断开引用,下一轮分配时会被回收
        }
        long elapsed = System.currentTimeMillis() - start;

        // 记录结束时的 GC 累计次数和累计暂停时间
        long gcCountAfter = 0, gcTimeAfter = 0;
        for (GarbageCollectorMXBean bean : beans) {
            gcCountAfter += bean.getCollectionCount();
            gcTimeAfter += bean.getCollectionTime();
        }

        System.out.println("总运行耗时        : " + elapsed + " ms");
        System.out.println("发生 GC 次数      : " + (gcCountAfter - gcCountBefore) + " 次");
        System.out.println("GC 累计耗时       : " + (gcTimeAfter - gcTimeBefore) + " ms (绝大部分是 STW,应用线程被冻结的时长;G1 含极少量并发阶段时间)");
        System.out.println();
        System.out.println("说明: GC 次数 > 0 证明真的发生了垃圾回收;");
        System.out.println("      累计耗时约等于所有 Stop-The-World 停顿之和(带并发阶段的收集器会略有高估)。");
    }
}

import java.util.ArrayList;
import java.util.List;

public class OomDemo {
    public static void main(String[] args) {
        // 一个一直被引用着的 List:里面的对象永远不会变成"垃圾"
        // 所以 GC 没法回收它们 → 堆迟早被撑满 → OutOfMemoryError
        List<byte[]> keepAlive = new ArrayList<>();

        int count = 0;                 // 记录成功塞进了多少个大对象
        int chunkSize = 1 * 1024 * 1024; // 每个对象 1MB(1兆 = 1024*1024 字节)
        long totalBytes = 0;           // 累计申请的字节数

        System.out.println("开始往 List 里不停塞 1MB 的大对象(它们都被引用着,不是垃圾)...");
        System.out.println("堆上限被 -Xmx16m 限制成约 16MB,看 GC 能不能救场。");
        System.out.println("--------------------------------------------------");

        try {
            while (true) {
                byte[] big = new byte[chunkSize]; // 申请一块 1MB 的内存
                count++;                          // 先记数,再加进 List
                totalBytes += chunkSize;
                keepAlive.add(big);               // 加进 List → 一直被引用 → GC 清不掉
                System.out.println("已成功塞入第 " + count + " 个对象,累计约 "
                        + (totalBytes / (1024 * 1024)) + " MB");
            }
        } catch (OutOfMemoryError e) {
            // 关键:把 List 引用清掉,让这些大对象终于变成"垃圾",
            // 给后面的打印腾出内存,否则连报错都印不出来。
            keepAlive = null;
            // 用 try-catch 接住这个 Error,程序不会直接崩,而是优雅地报告
            System.out.println("--------------------------------------------------");
            System.out.println("砰!撑爆了!抛出了:" + e);
            System.out.println("内存真的不够用了:总共撑到约 " + count + " 个 1MB 对象(约 "
                    + (totalBytes / (1024 * 1024)) + " MB)就 OOM 了。");
            System.out.println("结论:这些对象一直被 List 引用着(不是垃圾),"
                    + "GC 无权回收 → 堆被撑满 → 真 OOM,GC 也救不了。");
        }
    }
}
